import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';

export async function runMotionZoomSmoke(page){
 const viewport=page.viewport(),previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()})),dir=await fs.mkdtemp(path.join(os.tmpdir(),'nagweb-zoom-'));let revision=0;
 async function ready(count=3){await page.waitForFunction(count=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.defaultView.__NAG_SCROLL_DIRECTOR?.[d.querySelector('.sc')?.dataset.id]&&d.querySelectorAll('.nw-zoom-card').length===count&&d.querySelector('[data-motion-canvas]')&&Array.from(d.querySelectorAll('[data-nw-stream-slot] img')).every(n=>n.complete&&n.naturalWidth>0);},{timeout:15000},count);}
 async function change(selector,value,count=3){const mark='zoom-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.zoomOld=mark;n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.zoomOld!==mark&&d.querySelector('.nw-zoom-card');},{timeout:10000},mark);await ready(count);}
 async function pose(progress,selector='.nw-motion-dialog iframe',gid){return page.$eval(selector,(f,{progress,gid})=>{const d=f.contentDocument,id=gid||d.querySelector('.sc').dataset.id;f.contentWindow.__NAG_SCROLL_DIRECTOR[id].set(progress);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,src:n.querySelector('img').getAttribute('src'),phase:n.dataset.nwStreamPhase,zoom:+n.dataset.nwZoomScale,pan:+n.dataset.nwZoomPan,alpha:+n.querySelector('canvas').style.opacity,z:+n.style.zIndex,left:n.style.left,top:n.style.top,width:n.style.width,height:n.style.height}));},{progress,gid});}
 async function actualScroll(selector,gid){await page.$eval(selector,f=>f.contentWindow.scrollTo(0,f.contentDocument.querySelector('.sc').offsetHeight/2-f.contentWindow.innerHeight/2));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()>.4,{},{selector,gid});const middle=await page.$eval(selector,(f,gid)=>({p:f.contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress(),phase:+f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase}),gid);assert.ok(Math.abs(middle.phase-(middle.p*100-20)/60*3)<.001);await page.$eval(selector,f=>f.contentWindow.scrollTo(0,0));await page.waitForFunction(({selector,gid})=>document.querySelector(selector).contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()<.05,{},{selector,gid});assert.equal(await page.$eval(selector,f=>f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.nwStreamPhase),'0.000000');}
 async function exported(gid){await page.evaluate(()=>{document.querySelector('#zoom-export')?.remove();const f=document.createElement('iframe');f.id='zoom-export';f.style.cssText='width:1280px;height:720px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>document.querySelector('#zoom-export')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[gid]&&document.querySelector('#zoom-export').contentDocument.querySelector('.nw-zoom-card'),{},gid);}
 async function pixel(progress,id,selector='.nw-motion-dialog iframe',gid){await pose(progress,selector,gid);return page.$eval(selector,(f,id)=>{const n=f.contentDocument.querySelector('[data-id="'+id+'"]'),c=n.querySelector('canvas'),clip=n.__nwMotionClip,x=clip.left+clip.width/2-parseFloat(n.style.left),y=clip.top+clip.height/2-parseFloat(n.style.top),sx=c.width/parseFloat(n.style.width),sy=c.height/parseFloat(n.style.height),p=Array.from(c.getContext('2d').getImageData(Math.floor(x*sx),Math.floor(y*sy),1,1).data);return{p,clip,zoom:+n.dataset.nwZoomScale,pan:+n.dataset.nwZoomPan};},id);}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,bg:'#527467',elements:[mkEl('label',{text:'Exterior',name:'Exterior'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];});const before=await page.evaluate(()=>({project:JSON.stringify(project),stored:localStorage.getItem(STORE_KEY),outside:sec().elements[0]}));
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="zoom-parallax"]');await ready();assert.equal(await page.$eval('[data-motion-config="duration"]',n=>n.value),'9');assert.equal(await page.$eval('[data-motion-stream-count]',n=>[n.min,n.max].join(',')),'2,8');assert.equal(await page.$eval('[data-motion-stream="zoomAmount"]',n=>[n.value,n.min,n.max].join(',')),'12,4,25');assert.equal(await page.$eval('[data-motion-stream="panDir"]',n=>n.value),'alternate');assert.equal(await page.$('[data-motion-stream="cardRatio"]'),null);
  const start=await pose(0),end=await pose(1);assert.deepEqual(start.map(({phase,...n})=>n),end.map(({phase,...n})=>n));const early=await pose(.1),late=await pose(.2);assert.ok(late[0].zoom>early[0].zoom&&late[0].pan<early[0].pan);const fading=await pose(.95/3);assert.equal(fading[0].alpha,1);assert.ok(fading[1].alpha>0&&fading[1].alpha<1&&fading[1].z>fading[0].z);
  for(const panDir of ['left','right','alternate']){await change('[data-motion-stream="panDir"]',panDir);const a=await pose(.4),b=await pose(.5);assert.ok((b[1].pan-a[1].pan)*(panDir==='left'?-1:1)>0);}
  await change('[data-motion-stream="zoomAmount"]','25');await change('[data-motion-stream-count]','8',8);await change('[data-motion-stream-count]','2',2);await change('[data-motion-stream-count]','3');assert.deepEqual((await pose(0)).map(n=>[n.id,n.src]),start.map(n=>[n.id,n.src]));await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+start[0].id+'"]');
  const wide=path.join(dir,'Drift.svg');await fs.writeFile(wide,'<svg xmlns="http://www.w3.org/2000/svg" width="4096" height="1024"><defs><linearGradient id="g"><stop stop-color="#000000"/><stop offset="1" stop-color="#ff0000"/></linearGradient></defs><rect width="4096" height="1024" fill="url(#g)"/></svg>');const upload=await page.$('[data-motion-content-panel] .crow:not([hidden]) [data-motion-upload]');await upload.uploadFile(wide);await page.waitForFunction(id=>document.querySelector('.nw-motion-dialog iframe')?.contentDocument?.querySelector('[data-id="'+id+'"] img')?.naturalWidth===4096,{},start[0].id);await ready();
  const p0=await pixel(.02,start[0].id),p1=await pixel(.24,start[0].id);assert.ok(Math.abs(p0.p[0]-p1.p[0])>10,'Pixels change as the full image drifts inside its fixed frame');
  for(const sample of [p0,p1]){const expected=await page.evaluate(s=>{const crop=NAGWEB_STREAM_MODEL.imageZoomCrop(4096,1024,s.clip.width,s.clip.height,s.zoom,s.pan,{x:50,y:50});return 255*(s.clip.width/2-crop.x)/crop.width;},sample);assert.ok(Math.abs(sample.p[0]-expected)<4,JSON.stringify({sample,expected}));assert.equal(sample.p[3],255);}
  await change('[data-motion-image-focus="x"]','0');const edge=await pixel(.02,start[0].id);assert.ok(edge.p[0]<p0.p[0]-10);await change('[data-motion-image-focus="x"]','50');await change('[data-motion-stream="panDir"]','left');
  const textures=await page.$eval('.nw-motion-dialog iframe',f=>{const w=f.contentWindow,d=f.contentDocument,clock=w.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id];for(let i=0;i<60;i++)clock.set(i/60);const native=d.createElement,draw=w.CanvasRenderingContext2D.prototype.drawImage;let created=0,max=0;d.createElement=function(...args){if(args[0]==='canvas')created++;return native.apply(this,args);};w.CanvasRenderingContext2D.prototype.drawImage=function(image,...args){if(image instanceof w.HTMLCanvasElement)max=Math.max(max,image.width,image.height);return draw.call(this,image,...args);};try{for(let i=0;i<60;i++)clock.set(i/60);return{created,max};}finally{d.createElement=native;w.CanvasRenderingContext2D.prototype.drawImage=draw;}});assert.equal(textures.created,0);assert.equal(textures.max,2048,'Whole source textures are bounded and reused');
  await pose(.95/3);const target=await page.$eval('.nw-motion-dialog iframe',f=>{const fr=f.getBoundingClientRect(),n=Array.from(f.contentDocument.querySelectorAll('[data-nw-stream-slot]')).filter(n=>n.__nwMotionVisible).sort((a,b)=>+b.style.zIndex-+a.style.zIndex)[0],r=n.offsetParent.getBoundingClientRect(),c=n.__nwMotionClip;return{id:n.dataset.id,x:fr.left+(r.left+c.left+c.width/2)*fr.width/f.clientWidth,y:fr.top+(r.top+c.top+c.height/2)*fr.height/f.clientHeight};});await page.mouse.click(target.x,target.y);await page.waitForFunction(id=>document.querySelector('[data-motion-layer="'+id+'"]').getAttribute('aria-pressed')==='true',{},target.id);
  await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/zoom-parallax-desktop.png'});
  await change('[data-motion-config="source"]','scroll');for(const [key,value] of [['turns','3'],['start','20'],['end','80'],['scrollLength','420']])await change('[data-motion-stream="'+key+'"]',value);assert.equal((await pose(.1))[0].phase,'0.000000');assert.equal((await pose(.5))[0].phase,'1.500000');assert.equal((await pose(.9))[0].phase,'3.000000');assert.equal(await page.evaluate(()=>JSON.stringify(project)),before.project);assert.equal(await page.evaluate(()=>localStorage.getItem(STORE_KEY)),before.stored);
  await page.click('[data-motion-library-tab="library"]');await page.$eval('[data-motion-library-name]',n=>n.value='Mi Zoom');await page.click('[data-motion-library-save]');const saved=await page.evaluate(()=>project.nwMotionLibrary.at(-1));assert.equal(saved.config.stream.kind,'zoom-parallax');assert.equal(saved.config.stream.zoomAmount,25);assert.equal(saved.config.stream.panDir,'left');await page.click('[data-motion-saved="'+saved.id+'"]');await ready();const copied=await pose(.35);assert.ok(copied.every(n=>!start.some(o=>o.id===n.id)));await page.click('[data-motion-insert-group]');const inserted=await page.evaluate(()=>{const g=sec().elements.find(e=>e.nwMotionInstance);return{gid:g.id,outside:sec().elements[0],length:sec().sdLength,enabled:sec().sdEnabled};});assert.equal(inserted.enabled,true);assert.equal(inserted.length,420);assert.deepEqual(inserted.outside,before.outside);await page.waitForFunction(id=>document.querySelector('#preview')?.contentWindow?.__NAG_SCROLL_DIRECTOR?.[id]&&document.querySelector('#preview').contentDocument.querySelector('.nw-zoom-card'),{},inserted.gid);await actualScroll('#preview',inserted.gid);await exported(inserted.gid);assert.deepEqual((await pose(.35,'#zoom-export',inserted.gid)).map(n=>n.src),copied.map(n=>n.src));await page.$eval('#zoom-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].live(),inserted.gid);await actualScroll('#zoom-export',inserted.gid);await page.evaluate(()=>document.querySelector('#zoom-export').remove());
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();await change('[data-motion-stream="panDir"]','right');await page.$eval('#preview',f=>f.contentDocument.body.dataset.zoomSaved='old');await page.click('[data-motion-save]');await page.waitForFunction(id=>{const f=document.querySelector('#preview');return f?.contentDocument?.body&&!f.contentDocument.body.dataset.zoomSaved&&f.contentWindow.__NAG_SCROLL_DIRECTOR?.[id]&&f.contentDocument.querySelector('.nw-zoom-card');},{},inserted.gid);await actualScroll('#preview',inserted.gid);const scroll=await page.evaluate(()=>JSON.stringify(project));
  await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),inserted.gid);await ready();assert.equal(await page.$eval('[data-motion-stream="panDir"]',n=>n.value),'right');await change('[data-motion-config="source"]','time');await change('[data-motion-config="duration"]','2');await page.click('[data-motion-save]');const loop=await page.evaluate(()=>JSON.stringify(project));assert.equal(await page.evaluate(()=>sec().sdEnabled),false);await exported(inserted.gid);const clock=await page.$eval('#zoom-export',(f,id)=>f.contentWindow.__NAG_SCROLL_DIRECTOR[id].progress(),inserted.gid);await page.waitForFunction(({gid,clock})=>document.querySelector('#zoom-export').contentWindow.__NAG_SCROLL_DIRECTOR[gid].progress()!==clock,{timeout:3000},{gid:inserted.gid,clock});await page.evaluate(()=>document.querySelector('#zoom-export').remove());await page.evaluate(()=>undo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),scroll);await page.evaluate(()=>redo());assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);assert.equal(await page.evaluate(id=>migrate(JSON.parse(JSON.stringify(project))).pages[0].sections[0].elements.find(e=>e.id===id).nwMotionInstance.stream.kind,inserted.gid),'zoom-parallax');
  await page.setViewport({width:390,height:844,deviceScaleFactor:1});await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="zoom-parallax"]');await ready();await change('[data-motion-stream="frameRatio"]','auto');await (await page.$('.nw-motion-dialog')).screenshot({path:'/tmp/nagweb-motion-visuals/zoom-parallax-mobile.png'});await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="start"]','80');await change('[data-motion-stream="end"]','90');await change('[data-motion-stream="turns"]','0.25');await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);assert.deepEqual(await pose(.1),await pose(.9));assert.equal((await pose(.1)).filter(n=>n.alpha===1).length,1,'Reduced motion retains a visible still');await change('[data-motion-stream="turns"]','2');assert.deepEqual(await pose(.1),await pose(.9));assert.equal((await pose(.9)).filter(n=>n.alpha===1).length,1);await page.emulateMediaFeatures([]);await page.click('[data-motion-close]');await page.setViewport(viewport);assert.equal(await page.evaluate(()=>JSON.stringify(project)),loop);
  await page.evaluate(()=>NAGWEB_MOTION_LAB.open());await page.click('[data-motion-template="zoom-parallax"]');await ready();await page.click('[data-motion-insert]');const scene=await page.evaluate(()=>({gid:sec().nwMotionSceneGroup,config:sec().elements.find(e=>e.nwMotionInstance).nwMotionInstance}));assert.equal(scene.config.template,'zoom-parallax');await page.evaluate(id=>NAGWEB_MOTION_LAB.edit(id),scene.gid);await ready();await page.click('[data-motion-close]');
  console.log('Zoom Parallax: controls, full-image drift pixels/focus, texture reuse/cap, front image click, count recovery, drafts/Library, real scroll after save, time loop, history/JSON/HTML, group/scene, mobile and reduced motion OK');
 }catch(error){await fs.mkdir('/tmp/nagweb-motion-visuals',{recursive:true});await page.screenshot({path:'/tmp/nagweb-motion-visuals/zoom-parallax-failure.png'}).catch(()=>{});throw error;}finally{await page.emulateMediaFeatures([]);await page.setViewport(viewport);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#zoom-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);await fs.rm(dir,{recursive:true,force:true});}
}
